files.game.js:
const config = {
  type: Phaser.AUTO,
  width: 800,
  height: 600,
  physics: {
    default: 'arcade',
    arcade: {
      debug: false
    }
  },
  scene: { preload, create, update }
};

let player, enemies, bullets, enemyBullets, cursors, fireButton;
let score = 0, scoreText, gameOver = false;
let lastFired = 0, enemyFireTimer = 0;

const game = new Phaser.Game(config);

function preload() {
  const graphics = this.make.graphics({ x: 0, y: 0, add: false });

  // Player (blue triangle)
  graphics.fillStyle(0x00aaff, 1);
  graphics.fillTriangle(16, 0, 0, 32, 32, 32);
  graphics.generateTexture('player', 32, 32);
  graphics.clear();

  // Enemy (red square)
  graphics.fillStyle(0xff0000, 1);
  graphics.fillRect(0, 0, 24, 24);
  graphics.generateTexture('enemy', 24, 24);
  graphics.clear();

  // Bullet (yellow circle)
  graphics.fillStyle(0xffff00, 1);
  graphics.fillCircle(4, 4, 4);
  graphics.generateTexture('bullet', 8, 8);
}

function create() {
  // Player
  player = this.physics.add.sprite(400, 500, 'player');
  player.setCollideWorldBounds(true);

  // Bullets
  bullets = this.physics.add.group({
    defaultKey: 'bullet',
    maxSize: 20
  });

  // Enemy bullets
  enemyBullets = this.physics.add.group({
    defaultKey: 'bullet',
    maxSize: 30
  });

  // Enemies
  enemies = this.physics.add.group();

  // Spawn enemies
  this.time.addEvent({
    delay: 1000,
    callback: spawnEnemy,
    callbackScope: this,
    loop: true
  });

  // Collisions
  this.physics.add.overlap(bullets, enemies, hitEnemy, null, this);
  this.physics.add.overlap(player, enemies, hitPlayer, null, this);
  this.physics.add.overlap(player, enemyBullets, hitPlayer, null, this);

  // Input
  cursors = this.input.keyboard.createCursorKeys();
  fireButton = this.input.keyboard.addKey(Phaser.Input.Keyboard.KeyCodes.SPACE);

  // Score
  scoreText = this.add.text(16, 16, 'Score: 0', {
    fontSize: '24px',
    fill: '#fff'
  });
}

function update(time) {
  if (gameOver) return;

  // Player movement
  if (cursors.left.isDown) {
    player.setVelocityX(-300);
  } else if (cursors.right.isDown) {
    player.setVelocityX(300);
  } else {
    player.setVelocityX(0);
  }

  if (cursors.up.isDown) {
    player.setVelocityY(-300);
  } else if (cursors.down.isDown) {
    player.setVelocityY(300);
  } else {
    player.setVelocityY(0);
  }

  // Firing
  if (fireButton.isDown && time > lastFired) {
    const bullet = bullets.get(player.x, player.y - 20);
    if (bullet) {
      bullet.setActive(true);
      bullet.setVisible(true);
      bullet.setVelocityY(-400);
      lastFired = time + 200;
    }
  }

  // Clean up bullets
  bullets.children.each(bullet => {
    if (bullet.y < 0) bullet.destroy();
  });

  enemyBullets.children.each(bullet => {
    if (bullet.y > 600) bullet.destroy();
  });

  // Enemy firing
  if (time > enemyFireTimer) {
    enemies.children.each(enemy => {
      if (Math.random() < 0.1) {
        const bullet = enemyBullets.get(enemy.x, enemy.y + 20);
        if (bullet) {
          bullet.setActive(true);
          bullet.setVisible(true);
          bullet.setVelocityY(200);
        }
      }
    });
    enemyFireTimer = time + 500;
  }
}

function spawnEnemy() {
  const x = Phaser.Math.Between(50, 750);
  const enemy = enemies.create(x, 50, 'enemy');
  enemy.setVelocityY(100);
}

function hitEnemy(bullet, enemy) {
  bullet.destroy();
  enemy.destroy();
  score += 10;
  scoreText.setText('Score: ' + score);
}

function hitPlayer(player, object) {
  player.destroy();
  gameOver = true;
  scoreText.setText('Game Over! Final Score: ' + score);
  this.add.text(400, 300, 'GAME OVER', {
    fontSize: '64px',
    fill: '#ff0000'
  }).setOrigin(0.5);
}
